INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (4101, 0, 'يبرز الأنشطة الرئيسية', 'It highlights the key activities', false),
  (4101, 1, 'يوفر فئات لتحديد المخاطر', 'It provides categories for identifying risks', true),
  (4101, 2, 'إلزامي لتنفيذ التقييم النوعي للمخاطر', 'It is mandatory for performing qualitative risk assessment', false),
  (4101, 3, 'مدخل مهم لمعظم الأدوات والأساليب الكمية', 'It is an important input to most quantitative tools and techniques', false),
  (4102, 0, 'الاحتمالية والأرجحية', 'Probability and likelihood', false),
