  (4298, 0, 'تحديث احتياطي الطوارئ للمشروع بناءً على النتائج الأولية.', 'Update the project contingency reserve based on the preliminary findings.', false),
  (4298, 1, 'إجراء التحليل النوعي للمخاطر بمشاركة المعنيين المناسبين.', 'Perform qualitative risk analysis with the participation of the appropriate stakeholders.', true),
  (4298, 2, 'مراجعة تقارير المشروعات السابقة للحصول على أفكار بشأن التعامل مع مواقف مشابهة.', 'Review reports from previous projects to obtain ideas on how to handle similar situations.', false),
  (4298, 3, 'تحديد اجتماع مع راعي المشروع لإجراء عصف ذهني حول استراتيجيات تخفيف المخاطر.', 'Schedule a meeting with the project sponsor to brainstorm risk mitigation strategies.', false),
  (4299, 0, 'قياس العلاقة بين الأسباب والنتائج استنادًا إلى بيئة المشروع.', 'Measure the relationship between causes and effects based on the project environment.', false),
  (4299, 1, 'تحليل شهية المخاطر وتصنيف الآثار المحتملة.', 'Analyze the risk appetite and categorize the potential impacts.', false),
  (4299, 2, 'وضع محفزات المخاطر وحدودها بناءً على ظروف المشروع.', 'Establish risk triggers and thresholds based on the project conditions.', true),
  (4299, 3, 'إنشاء أدوات وتقنيات لتحديد خصائص مخاطر المشروع.', 'Create tools and techniques to define the characteristics of the project risks.', false),
  (4300, 0, 'لتقليل احتمالية حدوث الخطر وتقليل تأثيره.', 'To reduce the probability of the risk occurring and reduce its impact', true),
  (4300, 1, 'لنقل احتمالية وقوع الخطر إلى طرف ثالث وتقليل تأثيره.', 'To transfer the probability of the risk occurring to a third party and reduce its impact', false),
  (4300, 2, 'لقبول احتمالية وقوع الخطر وتقليل تأثيره.', 'To accept the probability of the risk occurring and reduce its impact', false),
  (4300, 3, 'لزيادة احتمالية حدوث الخطر وتقليل تأثيره.', 'To increase the probability of the risk occurring and reduce its impact', false);

INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (4301, 0, 'نقل الخطر إلى المورد من خلال شروط تعاقدية مناسبة.', 'Transfer the risk to the supplier through appropriate contractual terms.', true),
  (4301, 1, 'قبول الخطر دون توثيقه.', 'Accept the risk without documenting it.', false),
  (4301, 2, 'تجاهل الخطر حتى يحدث فعليًا.', 'Ignore the risk until it actually occurs.', false),
  (4301, 3, 'زيادة الاحتياطي الإداري فقط.', 'Increase the management reserve only.', false),
  (4302, 0, 'خطة إدارة المشروع', 'Project management plan', true),
  (4302, 1, 'افتراضات المشروع', 'Project assumptions', false),
  (4302, 2, 'معايير تقييم المخاطر', 'Risk assessment criteria', false),
  (4302, 3, 'خطة إدارة المخاطر', 'Risk management plan', false),
  (4303, 0, 'وضع خطة استجابة لكل خطر محدد', 'Develop a response plan for each identified risk', false),
  (4303, 1, 'إجراء تحليل نوعي للمخاطر لتحديد أولويات المخاطر', 'Perform qualitative risk analysis to prioritize the risks', true),
  (4303, 2, 'إجراء تحليل كمي للمخاطر لتحليل المخاطر رقميًا', 'Perform quantitative risk analysis to analyze the risks numerically', false),
  (4303, 3, 'تنفيذ خطط الاستجابة للمخاطر المتفق عليها', 'Implement the agreed risk response plans', false),
  (4304, 0, 'تأثير العوامل الاقتصادية الخارجية في إجراءات الاستجابة للمخاطر.', 'The impact of external economic factors on the risk response actions', false),
  (4304, 1, 'تحديد المخاطر التي ليس لها هيكل مخصص لتقسيم العمل.', 'Identifying risks that do not have a dedicated work breakdown structure', false),
  (4304, 2, 'وقت الوصول إلى أعلى زيادة في تكاليف التعامل مع المخاطر وفقًا للجدول الزمني للمشروع.', 'The point at which the highest increase in risk-handling costs is reached according to the project schedule', false),
  (4304, 3, 'الاتجاهات التي توضح انخفاض مستوى التعرض للمخاطر نتيجة خطط الاستجابة.', 'Trends showing a decrease in the level of risk exposure as a result of the response plans', true),
  (4305, 0, 'تنفيذ إجراء الاستجابة المتفق عليه عند حدوث الخطر.', 'Implementing the agreed response action when the risk occurs', false),
  (4305, 1, 'تطوير الاستراتيجية العامة لإدارة المخاطر بهدف دمجها في المشروع.', 'Developing the overall risk management strategy in order to integrate it into the project', false),
  (4305, 2, 'متابعة المخاطر التي تم تحديدها، والحفاظ على صلاحية خطط الاستجابة.', 'Tracking the identified risks and keeping the response plans valid', true),
  (4305, 3, 'تقديم تقدير رقمي للتأثير الإجمالي للمخاطر في الأهداف.', 'Providing a numerical estimate of the overall effect of risks on the objectives', false),
  (4306, 0, 'الاعتماد على تقييمات المخاطر الخارجية الخاصة بالمشروع ومخرجاته لتحديد المخاطر.', 'Rely on external risk assessments of the project and its deliverables to identify the risks.', false),
  (4306, 1, 'الجمع بين التقييمات الفردية وورش العمل الجماعية لتحديد المخاطر وإعداد سجل مخاطر شامل للمشروع.', 'Combine individual assessments with group workshops to identify the risks and prepare a comprehensive risk register for the project.', true),
  (4306, 2, 'طلب تقييمات فردية للمشروع ومخرجاته لتحديد المخاطر.', 'Request individual assessments of the project and its deliverables to identify the risks.', false),
  (4306, 3, 'استخدام ورش العمل الجماعية لإجراء تقييمات جماعية للمخاطر وتحديدها.', 'Use group workshops to conduct collective risk assessments and identify the risks.', false),
  (4307, 0, 'إجراءات المخاطر الخاصة بالشركة', 'The company''s risk procedures', false),
  (4307, 1, 'ميثاق المشروع', 'The project charter', false),
  (4307, 2, 'خطة تحقيق المنافع', 'The benefits realization plan', true),
  (4307, 3, 'ميثاق الفريق', 'The team charter', false),
  (4308, 0, 'الانتظار حتى يقوم المورد بإبلاغ الفريق بوجود تأخير قبل اتخاذ أي إجراء أثناء تنفيذ المشروع.', 'Wait until the supplier notifies the team of a delay before taking any action during project execution', false),
  (4308, 1, 'الإقرار بوجود الخطر دون اتخاذ أي إجراء فوري، على افتراض أن المورد سيلتزم بموعد التسليم.', 'Acknowledge the risk without taking any immediate action, assuming the supplier will meet the delivery date', false),
  (4308, 2, 'تحديد موردين بديلين لتقليل الاعتماد على مورد واحد، وإضافة وقت احتياطي إلى الجدول الزمني كإجراء احتياطي.', 'Identify alternative suppliers to reduce dependence on a single supplier, and add buffer time to the schedule as a contingency measure', true),
  (4308, 3, 'التركيز على تحسين التواصل مع المورد باعتباره أحد عوامل نجاح المشروع.', 'Focus on improving communication with the supplier as one of the project''s success factors', false),
  (4309, 0, 'مخطط التقارب.', 'Affinity diagram', false),
  (4309, 1, 'هيكل تجزئة العمل.', 'Work breakdown structure', true),
  (4309, 2, 'محاكاة مونت كارلو.', 'Monte Carlo simulation', false),
