  (4392, 3, 'إلغاء سجل المخاطر', 'Cancel the Risk Register', false),
  (4393, 0, 'إبقاؤه فقط كخطر محتمل', 'Keep it only as a potential risk', false),
  (4393, 1, 'تسجيله كمشكلة وتنفيذ الاستجابة المناسبة', 'Record it as an issue and implement the appropriate response', true),
  (4393, 2, 'حذفه من جميع السجلات', 'Delete it from all records', false),
  (4393, 3, 'تأجيل التعامل معه إلى إغلاق المشروع', 'Defer dealing with it until project closure', false),
  (4394, 0, 'خطر متبقٍ', 'Residual risk', false),
  (4394, 1, 'خطر غير معروف', 'Unknown risk', false),
  (4394, 2, 'مشكلة', 'Issue', false),
  (4394, 3, 'خطر ثانوي', 'Secondary risk', true),
  (4395, 0, 'تحديد أصحاب المصلحة ذوي النفوذ', 'Identifying influential stakeholders', false),
  (4395, 1, 'تقدير مجموعة النتائج المحتملة واحتمالات تحقيق أهداف المشروع', 'Estimating the range of possible outcomes and the probabilities of achieving the project objectives', true),
  (4395, 2, 'إلغاء الحاجة إلى التحليل النوعي', 'Eliminating the need for qualitative analysis', false),
  (4395, 3, 'تحديد المسؤول عن كل خطر فقط', 'Identifying only the person responsible for each risk', false),
  (4396, 0, 'إغلاق الخطر خلال الاجتماع التالي لمجلس إدارة المخاطر والاحتفاظ بالخطر في سجل المخاطر.', 'Close the risk during the next Risk Board meeting and retain the risk in the Risk Register.', true),
  (4396, 1, 'تجاهل هذا الخطر والتركيز فقط على المخاطر ذات الصلة.', 'Ignore this risk and focus only on the relevant risks.', false),
  (4396, 2, 'إجراء تحليل للمخاطر لتحديد كيفية قبول الخطر غير المنطبق رسميًا.', 'Perform a risk analysis to determine how to formally accept the inapplicable risk.', false),
  (4396, 3, 'إزالة الخطر من سجل المخاطر وإبلاغ مدير المشروع أنه لم يعد صالحًا.', 'Remove the risk from the Risk Register and inform the Project Manager that it is no longer valid.', false),
  (4397, 0, 'التخطيط للاستجابات', 'Plan Risk Responses', false),
  (4397, 1, 'تحديد المخاطر', 'Identify Risks', false),
  (4397, 2, 'عملية المراقبة والتحكم في المخاطر', 'The risk monitoring and control process', true),
  (4397, 3, 'عملية إدارة المخاطر', 'The risk management process', false),
  (4398, 0, 'الدروس المستفادة', 'Lessons Learned', false),
  (4398, 1, 'خطة إدارة التواصل', 'Communications Management Plan', true),
  (4398, 2, 'سجل المشكلات', 'Issue Log', false),
  (4398, 3, 'خطة إدارة المخاطر', 'Risk Management Plan', false),
  (4399, 0, 'تحليل شجرة القرارات', 'Decision Tree Analysis', false),
  (4399, 1, 'هيكل تجزئة العمل', 'Work Breakdown Structure', false),
  (4399, 2, 'مخطط التقارب', 'Affinity Diagram', false),
  (4399, 3, 'هيكل تجزئة المخاطر', 'Risk Breakdown Structure', true),
