INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (4400, 3, 'القبول', 'Accept', false),
  (4401, 0, 'مناقشة الجدول الزمني للمشروع مع الراعي التنفيذي والاتفاق على استراتيجية لتحديث خطة إدارة المخاطر وخطط الاستجابة للمخاطر', 'Discuss the project schedule with the executive sponsor and agree on a strategy to update the Risk Management Plan and the risk response plans', true),
  (4401, 1, 'مراجعة الجدول الزمني للمشروع والتوصية بضغط الجدول الزمني و/أو ضغط المسار الحرج.', 'Review the project schedule and recommend schedule compression and/or crashing the critical path.', false),
  (4401, 2, 'طلب اجتماع فوري مع اللجنة التوجيهية، والإبلاغ عن حالة المشروع، واقتراح تخفيضات في نطاق المشروع لتوفير الوقت.', 'Request a meeting with the steering committee immediately, report the project status, and propose scope reductions to save time.', false),
  (4401, 3, 'تحديث خطط الاستجابة للمخاطر الحالية وتضمين المزيد من الموارد لإعادة المشروع إلى المسار الصحيح.', 'Update the existing risk response plans and include additional resources to bring the project back on track.', false),
  (4402, 0, 'تمديد الجدول الزمني للمشروع لاستيعاب توافر الخبير', 'Extend the project schedule to accommodate the expert''s availability', false),
  (4402, 1, 'استبدال الخبير بالموارد المسؤولة عن تلقي مخرجات الخبير لإنجاز تسليماتها.', 'Replace the expert with the resources that are responsible for receiving the expert''s outputs for their own deliverables.', false),
  (4402, 2, 'إدخال تخفيضات في النطاق للحد من الاعتماد على الخبير', 'Introduce scope reductions to limit the dependency on the expert', false),
  (4402, 3, 'تدريب الآخرين لتقليل عبء العمل على الخبير.', 'Train others to reduce the workload on the expert.', true),
  (4403, 0, 'ميزانية الإدارة', 'Management budget', false),
  (4403, 1, 'موازنة المشروع', 'Project budget', false),
  (4403, 2, 'الاحتياطي الإداري', 'Management Reserve', false),
  (4403, 3, 'احتياطي الطوارئ', 'Contingency Reserve', true),
  (4404, 0, 'ضبط خطط الاستجابة للمخاطر للتعامل بفاعلية مع المخاطر المحددة', 'Adjust the risk response plans to address the identified risks effectively', false),
  (4404, 1, 'تدريب المجموعات الوظيفية على كيفية إجراء العملية بشكل صحيح', 'Train the functional groups on how to perform the process correctly', true),
  (4404, 2, 'الاستعانة بمستشارين لتنفيذ الاستجابة للمخاطر ووضع خطة الاستجابة للمخاطر', 'Engage consultants to perform the risk response and develop the risk response plan', false),
  (4404, 3, 'مطالبة المديرين الوظيفيين بتحسين سجل المخاطر وعملية إدارة المخاطر', 'Ask the functional managers to improve the Risk Register and the risk process', false),
  (4405, 0, 'تصعيد الموقف إلى مدير المخاطر وانتظار تعليماته', 'Escalate the situation to the Risk Manager and wait for instructions', false),
  (4405, 1, 'إجراء تحليل لتحديد السبب الجذري للاستجابة الفاشلة', 'Perform an analysis to determine the root cause of the failed response', true),
  (4405, 2, 'تطوير حل فعال لحماية الشبكة بسرعة لتقليل المخاطر', 'Develop an effective solution to protect the network quickly in order to reduce the risk', false),
  (4405, 3, 'تطبيق إجراء للتخلص من أثر التهديد أو تخفيفه', 'Apply an action to eliminate or mitigate the impact of the threat', false),
  (4406, 0, 'مطالبة الفريق بإجراء تحليل القيمة المكتسبة', 'Ask the team to perform earned value analysis', false),
  (4406, 1, 'استخدام تغيير المخاطر من خلال إجراء تقييم PESTLE', 'Use a risk change by performing a PESTLE assessment', false),
  (4406, 2, 'مراجعة الدروس المستفادة من المشاريع الأخرى', 'Review lessons learned from other projects', true),
  (4406, 3, 'مطالبة الفريق بإجراء تحليل مونت كارلو (Monte Carlo)', 'Ask the team to perform a Monte Carlo analysis', false),
  (4407, 0, 'متابعة المخاطر والتحكم فيها', 'Monitor and Control Risks', false),
  (4407, 1, 'إجراء التحليل الكمي للمخاطر', 'Perform Quantitative Risk Analysis', false),
  (4407, 2, 'إجراء التحليل النوعي للمخاطر', 'Perform Qualitative Risk Analysis', true),
  (4407, 3, 'وضع خطة إدارة المخاطر', 'Plan Risk Management', false),
  (4408, 0, 'الاتصال بالمهنيين الآخرين لمعرفة إن كان الطلب قيد المعالجة', 'Contact the other professionals to find out whether the request is being processed', false),
  (4408, 1, 'تنفيذ استراتيجية الاستجابة للمخاطر وتسجيلها في سجل المخاطر', 'Implement a risk response strategy and record it in the risk register', true),
  (4408, 2, 'إبلاغ العميل وراعي المشروع بأنه تم تقديم الطلب', 'Inform the client and the project sponsor that the request has been submitted', false),
  (4408, 3, 'إجراء تحليل لتأكيد صلاحية الطلب قبل الإرسال', 'Perform an analysis to confirm the validity of the request before submitting it', false),
  (4409, 0, 'تحديث خطة إدارة الاتصالات لتجنب المشكلات المستقبلية', 'Update the communications management plan to avoid future issues', false),
  (4409, 1, 'وضع خطط الاستجابة للمخاطر لجميع المخاطر المحددة', 'Develop risk response plans for all identified risks', false),
  (4409, 2, 'مراقبة المخاطر الثانوية والمتبقية ومراجعة خطط المخاطر المرتبطة', 'Monitor secondary and residual risks and review the associated risk plans', true),
  (4409, 3, 'تحديث خطة إدارة المخاطر السنوية', 'Update the annual risk management plan', false),
  (4410, 0, 'ربح 100,000 دولار أمريكي', 'A gain of $100,000', false),
  (4410, 1, 'خسارة 20,000 دولار أمريكي', 'A loss of $20,000', false),
  (4410, 2, 'خسارة 40,000 دولار أمريكي', 'A loss of $40,000', false),
  (4410, 3, 'ربح 20,000 دولار أمريكي', 'A gain of $20,000', true),
  (4411, 0, 'إضافة الخطر إلى قائمة المراقبة', 'Add the risk to the watch list', true),
  (4411, 1, 'طلب التوجيه من الخبراء المتخصصين (SMEs)', 'Request guidance from subject matter experts (SMEs)', false),
  (4411, 2, 'إبلاغ المهنيين عن هذا الخطر', 'Inform the professionals about this risk', false),
  (4411, 3, 'تجاهل هذا الخطر لأنه ليس حرجًا', 'Ignore this risk because it is not critical', false),
  (4412, 0, 'تخطيط الاستجابة للمخاطر', 'Plan Risk Responses', false),
  (4412, 1, 'التحليل الكمي للمخاطر', 'Quantitative Risk Analysis', true),
  (4412, 2, 'متابعة المخاطر والتحكم فيها', 'Monitor and Control Risks', false),
  (4412, 3, 'تقييم مدى إلحاح المخاطر', 'Risk Urgency Assessment', false),
  (4413, 0, 'إتاحة عملية تحديد مخاطر المشروع الفردية المختلفة', 'Provide a process for identifying the different individual project risks', false),
  (4413, 1, 'تحسين جمع بيانات الأداء وتحليلها وتوفيرها', 'Improve the collection, analysis, and provision of performance data', false),
  (4413, 2, 'توفير إجراء معياري لتحديد المخاطر والإبلاغ عنها', 'Provide a standard procedure for identifying and reporting risks', true),
  (4413, 3, 'مراقبة التأثير مقابل التعرض الكلي لمخاطر المشروع', 'Monitor impact against overall project risk exposure', true),
  (4413, 4, 'تحديد مصادر المخاطر ومسؤولية مراقبة المحفظة', 'Identify risk sources and portfolio monitoring responsibility', true),
  (4414, 0, 'وضع علامة على كل خطر تم تحديده كأولوية قصوى وأي مخاطر مستقبلية كأولوية أقل', 'Flag every identified risk as top priority and any future risks as lower priority', false),
  (4414, 1, 'إجراء تحليل الحساسية وتحديد الأولوية الصحيحة لكل من المخاطر المحددة', 'Perform a sensitivity analysis and determine the correct priority for each of the identified risks', true),
  (4414, 2, 'الاستفسار من راعي المشروع عما إذا كان من الممكن إسناد الأولوية نفسها لجميع المخاطر في سجل المخاطر', 'Ask the project sponsor whether all risks in the risk register may be assigned the same priority', false),
  (4414, 3, 'الاتفاق مع الخبير المتخصص والتعامل مع كل خطر بأولوية متساوية وإبلاغ جميع المعنيين', 'Agree with the subject matter expert, treat every risk with equal priority, and inform all stakeholders', false),
  (4415, 0, 'تحديث الجدول الزمني للمشروع وإضافة مهام تنفيذ لصاحب الاستجابة للمخاطر', 'Update the project schedule and add implementation tasks for the risk response owner', false),
  (4415, 1, 'توفير تدريب منتظم لأصحاب المخاطر لتنفيذ الخطة', 'Provide regular training to the risk owners on implementing the plan', true),
  (4415, 2, 'تحديد محفزات المخاطر وعتباتها في خطة الاستجابة للمخاطر', 'Define risk triggers and thresholds in the risk response plan', false),
  (4415, 3, 'زيادة التواصل للتأثير على استجابات المعنيين للمخاطر', 'Increase communication to influence stakeholder responses to risks', false),
  (4416, 0, 'توظيف موارد إضافية وضغط الجدول الزمني', 'Hire additional resources and crash the schedule', true),
  (4416, 1, 'إجراء التحليل النوعي للمخاطر في المشروع', 'Perform Qualitative Risk Analysis on the project', false),
  (4416, 2, 'التخفيف من حدة المخاطر المحددة في تحليل الحساسية', 'Mitigate the risks identified in the sensitivity analysis', false),
  (4416, 3, 'تحديث سجل الافتراضات / الاستثناءات', 'Update the assumption / exclusion log', false),
  (4417, 0, 'إعداد خطة استجابة طارئة لتنفيذها عند حدوث تغييرات', 'Prepare a contingency response plan to be implemented when changes occur', true),
  (4417, 1, 'الطلب من مدير المشروع الآخر التأكيد رسميًا على التاريخ الجديد كتابةً', 'Ask the other project manager to formally confirm the new date in writing', false),
  (4417, 2, 'طلب إضافة مدير المشروع الآخر إلى التقارير ذات الصلة', 'Request that the other project manager be added to the relevant reports', false),
  (4417, 3, 'الطلب من مدير المشروع الآخر إعلامه إذا كان من المتوقع حدوث أي تغيير إضافي', 'Ask the other project manager to inform him if any further change is expected', false),
  (4418, 0, 'يحدد المشروع مصفوفة مخاطر على مستوى المشروع استنادًا إلى احتمالية الحدوث والعواقب المحتملة المقبولة.', 'A project defines a project-level risk matrix based on the probability of occurrence and the acceptable potential consequences.', false),
  (4418, 1, 'يُبلغ الفريق عن المخاطر التي يقل أثرها عن شهية المخاطر المحددة للمورد المعني في قسم بنود الاهتمام من تقرير حالة المشروع بدلًا من سجل المخاطر.', 'The team reports risks whose impact is below the defined appetite of the designated resource in the items-of-interest section of the project status report rather than in the Risk Register.', true),
  (4418, 2, 'حددت إحدى وحدات الأعمال أن مخاطر المشاريع الكبرى هي المخاطر التي تزيد آثارها عن 100 مليون دولار أمريكي.', 'A business unit has established that major project risks are those with impacts greater than US$100 million.', true),
  (4418, 3, 'تسمح مؤسسة ما بوضع طريقة متسقة لتقييم المخاطر والاستجابة لها في جميع أنحاء المؤسسة.', 'An organization allows a consistent method for assessing and responding to risks to be established throughout the organization.', false),
  (4418, 4, 'تعيد شركة بناء النظر في عرض مشروع مشترك بسبب وجود احتمال خسارة بنسبة 40%.', 'A construction company reconsiders a joint venture project proposal because there is a 40% probability of loss.', true),
  (4419, 0, 'تنفيذ الاستراتيجيات فورًا.', 'Implement the strategies immediately.', false),
  (4419, 1, 'ضمان اعتماد الاستراتيجيات من قبل المعنيين.', 'Ensure that the strategies are approved by the stakeholders.', true),
  (4419, 2, 'تنفيذ الاستراتيجيات بعد اكتمال تحليل المخاطر.', 'Implement the strategies after the risk analysis is complete.', false),
  (4419, 3, 'مراجعة الاستراتيجيات بشكل دوري.', 'Review the strategies periodically.', false),
  (4420, 0, 'سجل المخاطر', 'Risk Register', true),
  (4420, 1, 'أساس التقديرات', 'Basis of estimates', false),
  (4420, 2, 'سجل التغيير', 'Change log', false),
  (4420, 3, 'سجل الأعمال المتراكمة المعدّل حسب المخاطر', 'Risk-adjusted backlog', true),
  (4420, 4, 'سجل الافتراضات', 'Assumption log', true),
  (4421, 0, 'نقل ملكية المخاطر إلى العميل.', 'Transfer ownership of the risks to the customer.', false),
  (4421, 1, 'تنفيذ استراتيجيات التعامل مع هذه المخاطر.', 'Implement the strategies for addressing these risks.', true),
  (4421, 2, 'طلب احتياطي إداري إضافي لهذه المخاطر.', 'Request an additional Management Reserve for these risks.', false),
  (4421, 3, 'تقليل احتمالية هذه المخاطر في سجل المخاطر.', 'Reduce the probability of these risks in the Risk Register.', false),
  (4422, 0, 'التأكد من بقاء راعي المشروع على اطلاع تام.', 'Ensure that the project sponsor remains fully informed.', false),
  (4422, 1, 'متابعة التكاليف مع التدخل عند الضرورة.', 'Track costs and intervene when necessary.', false),
  (4422, 2, 'ترتيب عمليات تدقيق دورية لعملية إدارة المخاطر.', 'Arrange periodic audits of the risk management process.', true),
  (4422, 3, 'إبلاغ المعنيين بحالة المخاطر بانتظام.', 'Report the risk status to the stakeholders regularly.', false),
  (4423, 0, 'تنفيذ استراتيجيات الاستجابة للمخاطر من خطة المخاطر.', 'Implement the risk response strategies from the risk plan.', false),
  (4423, 1, 'مناقشة المخاطر المحددة وتقييمها مع فريق المشروع.', 'Discuss and assess the identified risks with the project team.', true),
  (4423, 2, 'إخبار الراعي بأنه يجب إضافة هذه المخاطر وفقًا لخبرته.', 'Tell the sponsor that these risks must be added based on the project manager''s experience.', false),
  (4423, 3, 'إضافة المخاطر إلى سجل المخاطر وتحديد احتياطي للطوارئ.', 'Add the risks to the Risk Register and define a contingency.', false),
  (4424, 0, 'إشراك فريق المشروع والتأثير فيه من خلال أنشطة المشاركة في المخاطر مثل ورش العمل.', 'Involve and influence the project team through risk engagement activities such as workshops.', true),
  (4424, 1, 'التأكد من أن جميع المعنيين يستخدمون لجنة المخاطر بما يتسق مع خطة إدارة المخاطر.', 'Ensure that the risk committee is used by all stakeholders in a manner consistent with the Risk Management Plan.', false),
  (4424, 2, 'جدولة اجتماع لمراجعة عتبات المخاطر الواقعية وتطويرها مع فريق المشروع.', 'Schedule a meeting to review and develop realistic Risk Thresholds with the project team.', false),
  (4424, 3, 'التأكد من تحديد مسؤوليات إدارة المخاطر بوضوح في خطة إدارة المخاطر.', 'Ensure that risk management responsibilities are clearly defined in the Risk Management Plan.', false),
  (4425, 0, 'التعاقد مع مورد آخر إذا فات موعد تسليم العنصر.', 'Contract with another supplier if the item delivery is missed.', false),
  (4425, 1, 'تسجيل الخطر على أنه ذو أثر متوسط.', 'Record the risk as having a medium impact.', false),
  (4425, 2, 'التنسيق مع المعنيين بشأن عتبة المخاطر.', 'Align with the stakeholders on the Risk Threshold.', true),
  (4425, 3, 'الاتفاق مع المورد الخارجي على الجدول الزمني.', 'Agree on the schedule with the external supplier.', false),
  (4426, 0, 'تقليل الاتصالات لتشمل مجموعة صغيرة فقط عندما يتعين اتخاذ قرارات تتعلق بالمخاطر الرئيسية.', 'Limit communications to a small group only when decisions on key risks have to be made.', false),
  (4426, 1, 'تصعيد المواضيع المتعلقة بالمخاطر إلى مدير المشروع والراعي للتأكد من أنهما على دراية كاملة بالتأثيرات المحتملة.', 'Escalate risk-related topics to the project manager and the sponsor to ensure that they are fully aware of the potential impacts.', false),
  (4426, 2, 'تحمل مسؤولية عملية إدارة المخاطر والتقليل من أي تفاعلات مع المعنيين المطلوبين.', 'Take ownership of the risk management process and minimize any interactions with the required stakeholders.', false),
  (4426, 3, 'مراقبة الاختلافات والاتجاهات بشكل متكرر طوال المشروع واتخاذ الإجراءات وفقًا لذلك.', 'Monitor variances and trends frequently throughout the project and take action accordingly.', true),
  (4427, 0, 'قام المعنيون بإعداد افتراضات الجدول الزمني الأولية بناءً على نتائج المشروع الأخير فقط.', 'The stakeholders prepared the initial schedule assumptions based only on the results of the most recent project.', true),
  (4427, 1, 'لم يقدم الراعي النتائج الكاملة للمعنيين ولم يقم بتحديث الافتراضات الأولية.', 'The sponsor did not provide the complete results to the stakeholders and did not update the initial assumptions.', false),
  (4427, 2, 'تم تضمين تعويضات الفريق، وقدّر الفريق مبلغ الدفع مقابل الالتزام بالموعد النهائي للمشروع.', 'Team compensation was included, and the team estimated the payment for meeting the project deadline.', false),
  (4427, 3, 'لقد تغيرت اللوائح الحكومية في الأسبوع الماضي، وبالتالي هناك حاجة إلى عمليات موافقة إضافية.', 'Government regulations changed last week, and therefore additional approval processes are required.', false),
  (4428, 0, 'تحليل الحساسية', 'Sensitivity Analysis', false),
  (4428, 1, 'اختبار ألفا', 'Alpha testing', false),
  (4428, 2, 'محاكاة مونت كارلو (Monte Carlo)', 'Monte Carlo Simulation', false),
  (4428, 3, 'التحليل النوعي', 'Qualitative analysis', true),
  (4429, 0, 'استخدام المعلومات لورشة عمل المخاطر.', 'Use the information for a risk workshop.', false),
  (4429, 1, 'إنشاء سجل للمشكلات للمشاركة مع الفريق.', 'Create an issue log to share with the team.', false),
  (4429, 2, 'توثيق المشكلات في الدروس المستفادة.', 'Document the issues in the lessons learned.', false),
  (4429, 3, 'تحسين المراقبة والتحكم في الأنشطة.', 'Improve the monitoring and control of activities.', true),
  (4430, 0, 'استخدام نهج تنبؤي للتسليم', 'Using a predictive delivery approach', true),
  (4430, 1, 'استخدام نهج هجين للتسليم', 'Using a hybrid delivery approach', false),
  (4430, 2, 'استخدام نهج تكيفي للتسليم', 'Using an adaptive delivery approach', false),
  (4430, 3, 'استخدام نهج رشيق للتسليم', 'Using an agile delivery approach', false),
  (4431, 0, 'تأثير الخطر', 'The effect of the risk', false),
  (4431, 1, 'تأثير المخاطر', 'The effect of the risks', false),
  (4431, 2, 'حالة الخطر', 'The risk condition', true),
  (4431, 3, 'درجة المخاطر', 'The risk score', false),
  (4432, 0, 'إجراء اجتماع مع الخبراء في الموضوع', 'Hold a meeting with subject matter experts', false),
  (4432, 1, 'تحديد الأولويات بعد التحليل الكمي', 'Prioritize the risks after quantitative analysis', false),
  (4432, 2, 'إعطاء الأولوية للمعنيين المتضررين', 'Give priority to the affected stakeholders', false),
  (4432, 3, 'إجراء تحليل نوعي', 'Perform qualitative analysis', true),
  (4433, 0, 'تحديد مستوى شهية المخاطر الأفضل توافقًا مع الأنشطة غير المتوافقة.', 'Determine the level of risk appetite that BEST aligns with the activities that are not aligned.', false),
  (4433, 1, 'مواءمة عتبات مخاطر المشروع مع ثقافة المنظمة وشهيتها للمخاطرة.', 'Align the project risk thresholds with the organizational culture and its risk appetite.', true),
  (4433, 2, 'اختبار أفضل شهية للمخاطرة لتجنب أي تأثير سلبي على المشروع.', 'Test the BEST risk appetite in order to avoid any negative impact on the project.', false),
  (4433, 3, 'المواءمة مع استراتيجية المخاطر الخاصة براعي المشروع لأنه من المعنيين الرئيسيين.', 'Align with the project sponsor''s risk strategy because the sponsor is a key stakeholder.', false),
  (4434, 0, 'إيقاف المشروع لإجراء تقييم بيئي شامل.', 'Stop the project in order to conduct a comprehensive environmental assessment.', false),
  (4434, 1, 'تعديل الجدول الزمني للمشروع لاستيعاب استجابة شاملة للمخاطر.', 'Adjust the project schedule to accommodate a comprehensive risk response.', false),
  (4434, 2, 'استشارة متخصصين في البيئة لوضع خطط تخفيف مخصصة.', 'Consult environmental specialists to develop tailored mitigation plans.', true),
  (4434, 3, 'الاستمرار باستخدام حل مؤقت أثناء إعداد خطة تفصيلية للاستجابة للمخاطر.', 'Continue using a temporary workaround while a detailed risk response plan is prepared.', false),
  (4435, 0, 'التحليل النوعي', 'Qualitative analysis', true),
  (4435, 1, 'تحليل الحساسية', 'Sensitivity analysis', false),
  (4435, 2, 'تحليل التأثير', 'Impact analysis', false),
  (4435, 3, 'تحليل إحصائي', 'Statistical analysis', false),
  (4436, 0, 'تأكيد عتبات مخاطر المعنيين بناءً على شهيتهم للمخاطرة.', 'Confirm the stakeholders'' risk thresholds based on their risk appetite.', true),
  (4436, 1, 'إجراء تحديث للمخاطر لملء سجل المخاطر.', 'Perform a risk update to populate the Risk Register.', false),
  (4436, 2, 'الانتقال إلى عينة منخفضة المخاطر بنسبة 5% حول هذه التكلفة.', 'Move to a low-risk sample of 5% around this cost.', false),
  (4436, 3, 'الانتقال إلى عينة عالية المخاطر قدرها 10% حول هذه التكلفة.', 'Move to a high-risk sample of 10% around this cost.', false),
  (4437, 0, 'ينبغي لمدير تكنولوجيا المعلومات أن يقود تنفيذ البنية التحتية.', 'The IT manager should lead the implementation of the infrastructure.', false),
  (4437, 1, 'ينبغي إضافة مدير تكنولوجيا المعلومات كراعٍ للمشروع.', 'The IT manager should be added as the project sponsor.', false),
  (4437, 2, 'ينبغي لمدير تكنولوجيا المعلومات أن يحسّن الخطط الأساسية للمشروع.', 'The IT manager should refine the project baselines.', false),
  (4437, 3, 'ينبغي إدراج مدير تكنولوجيا المعلومات كمالك للمخاطر.', 'The IT manager should be included as a Risk Owner.', true),
  (4438, 0, 'تصعيد موضوع التوظيف إلى الراعي وطلب المزيد من ميزانية الطوارئ.', 'Escalate the staffing matter to the sponsor and request additional contingency budget.', false),
  (4438, 1, 'تنفيذ أسلوب رشيق منضبط وإبلاغ المعنيين وفقًا لذلك.', 'Implement a disciplined agile method and inform the stakeholders accordingly.', false),
  (4438, 2, 'مراجعة ميثاق المشروع لإجراء تعديلات على النطاق وتوقيعها مع العميل.', 'Review the project charter to make scope adjustments and sign them with the customer.', false),
  (4438, 3, 'الدعوة لعقد اجتماع لفريق المشروع لمراجعة استراتيجيات المخاطر وإجراء التعديلات اللازمة.', 'Call a project team meeting to review the risk strategies and make the necessary adjustments.', true),
  (4439, 0, 'بدء التحليل الكمي لفهم التأثير.', 'Initiate quantitative analysis to understand the impact.', false),
  (4439, 1, 'نقل الخطر إلى الفريق الخارجي.', 'Transfer the risk to the external team.', false),
  (4439, 2, 'مطالبة مالكي المخاطر بمراجعة خطة الاستجابة للمخاطر.', 'Ask the Risk Owners to review the risk response plan.', true),
  (4439, 3, 'ضغط الجدول الزمني للتخفيف من عواقب الخطر.', 'Compress the schedule to mitigate the consequences of the risk.', false),
  (4440, 0, 'مراجعة النتائج الواردة في وثائق إغلاق المشروع أ واقتراح عملية تنظيمية جديدة لإدارة مخاطر المحفظة.', 'Review the findings contained in the Project A closing documents and propose a new organizational process for portfolio risk management.', false),
  (4440, 1, 'دمج سجلات المخاطر للمشروع أ والمشروع ب وتحديد ما إذا كانت هناك أي فرص إضافية بين المشاريع يمكن استغلالها.', 'Merge the Risk Registers of Project A and Project B and determine whether there are any additional cross-project opportunities that can be exploited.', false),
  (4440, 2, 'مواصلة تنفيذ خطة التخفيف من المخاطر لتجنب أي تأثير إضافي على الجدول الزمني للمشروع أ.', 'Continue implementing the risk mitigation plan in order to avoid any additional impact on the schedule of Project A.', false),
  (4440, 3, 'التشاور مع مدير المخاطر في المشروع ب وتحديد المجالات التي قد يوجد فيها تآزر بين خطط إدارة المخاطر لكلا المشروعين.', 'Consult with the risk manager of Project B and identify the areas in which there may be synergy between the risk management plans of both projects.', true),
  (4441, 0, 'التأكد من أن الاحتياطيات الإدارية كافية لتغطية خطط التخفيف لجميع المخاطر التي تم تحديدها.', 'Ensure that the management reserves are sufficient to cover the mitigation plans for all identified risks.', false),
  (4441, 1, 'مراقبة الحالة والإشراف على تنفيذ خطة الاستجابة للمخاطر لكل خطر تم تحديده.', 'Monitor the status of, and oversee the implementation of, the risk response plan for each identified risk.', true),
  (4441, 2, 'تخصيص موارد المشروع وتثبيتها وفقًا لأولوية المخاطر الأولية لجميع المخاطر التي تم تحديدها.', 'Allocate and lock project resources according to the initial risk priority for all identified risks.', false),
  (4441, 3, 'التحقق بشكل دوري وإعداد التقارير عن حالة المخاطر التي تم تحديدها وفقًا لأولوياتها.', 'Periodically verify and report on the status of the identified risks according to their priority.', true),
  (4441, 4, 'التحقق من إمكانية حدوث أي مخاطر محددة أم لا وتنفيذ خطة الاستجابة للمخاطر.', 'Verify whether or not any identified risk may occur and implement the risk response plan.', true),
  (4442, 0, 'المعنيون الداخليون فقط', 'Internal stakeholders only', false),
  (4442, 1, 'المعنيون الداخليون والخارجيون', 'Internal and external stakeholders', true),
  (4442, 2, 'فريق المشروع الأساسي', 'The core project team', false),
  (4442, 3, 'المعنيون الرئيسيون في الأعمال التجارية', 'The key business stakeholders', false),
  (4443, 0, 'تحليل المخاطر وإضافتها إلى سجل المخاطر لمواصلة العملية.', 'Analyze the risks and add them to the Risk Register in order to continue the process.', true),
  (4443, 1, 'تعيين مجموعات منفصلة للمعنيين للمخاطر الإيجابية والمخاطر السلبية.', 'Assign separate stakeholder groups to the positive risks and to the negative risks.', false),
  (4443, 2, 'إعطاء الأولوية للفرص التي من الأكثر احتمالًا أن تجلب فوائد للمشروع.', 'Prioritize the opportunities that are MOST likely to bring benefits to the project.', false),
  (4443, 3, 'إنشاء مشروع منفصل لإدارة المخاطر الإيجابية والتهديدات حصريًا.', 'Create a separate project to manage positive risks and threats exclusively.', false),
  (4444, 0, 'تخفيف المخاطر من خلال مطالبة عضو الفريق بجمع المزيد من المعلومات.', 'Mitigate the risk by asking the team member to gather more information.', false),
  (4444, 1, 'إضافة المخاطر إلى سجل المشكلات ومراجعتها عند توفر المزيد من المعلومات.', 'Add the risk to the issue log and review it when more information becomes available.', false),
  (4444, 2, 'ترتيب اجتماع مع المعني لمناقشة المخاطر والمعلومات.', 'Arrange a meeting with the stakeholder to discuss the risk and the information.', false),
  (4444, 3, 'إضافة المخاطر إلى سجل المخاطر وجمع المعلومات حول احتماليتها وتأثيرها.', 'Add the risk to the Risk Register and gather information on its probability and impact.', true),
  (4445, 0, 'زيادة مراقبة المخاطر الكامنة.', 'Increase the monitoring of inherent risk.', false),
  (4445, 1, 'زيادة مراقبة المخاطر المتبقية.', 'Increase the monitoring of residual risk.', false),
  (4445, 2, 'إعادة تقييم مستوى المخاطر الكامنة.', 'Reassess the level of inherent risk.', false),
  (4445, 3, 'إعادة تقييم مستوى المخاطر المتبقية.', 'Reassess the level of residual risk.', true),
  (4446, 0, 'هيكل تجزئة المخاطر (RBS)', 'Risk Breakdown Structure', false),
  (4446, 1, 'مخطط احتراق المخاطر', 'Risk Burndown Chart', false),
  (4446, 2, 'مخطط إيشيكاوا', 'Ishikawa diagram', true),
  (4446, 3, 'مخطط التقارب', 'Affinity diagram', false),
  (4447, 0, 'تطوير حل فعال لحماية الشبكة بسرعة للتخفيف من المخاطر.', 'Quickly develop an effective solution to protect the network in order to mitigate the risk.', false),
  (4447, 1, 'إجراء تحليل لتحديد السبب الجذري للاستجابة الفاشلة.', 'Perform an analysis to determine the root cause of the failed response.', true),
  (4447, 2, 'تصعيد الأمر إلى مدير المخاطر وانتظار تعليماته.', 'Escalate the matter to the risk manager and wait for instructions.', false),
  (4447, 3, 'تطبيق حل مؤقت للقضاء على التهديد أو التخفيف من تأثيره.', 'Apply a workaround to eliminate the threat or reduce its impact.', false),
  (4448, 0, 'الجدول الزمني وافتراضات الموارد', 'The schedule and resource assumptions', true),
  (4448, 1, 'مصفوفة تأثير المخاطر', 'The risk impact matrix', false),
  (4448, 2, 'هيكل تجزئة العمل (WBS)', 'The Work Breakdown Structure (WBS)', false),
  (4448, 3, 'احتياطيات الطوارئ', 'The contingency reserves', false),
  (4449, 0, 'تحديث سجل المخاطر والتحضير لتحليل محاكاة مونت كارلو (Monte Carlo).', 'Update the Risk Register and prepare for a Monte Carlo analysis.', false),
  (4449, 1, 'تحديث سجل الافتراضات/الاستبعادات بالمعلومات الجديدة.', 'Update the assumption/exclusion log with the new information.', false),
  (4449, 2, 'إجراء تحليل نوعي للمخاطر وتحديث النتائج.', 'Perform a Qualitative Risk Analysis and update the results.', false);

INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct) VALUES
  (4449, 3, 'إجراء تحليل كمي للمخاطر وتحديث النتائج.', 'Perform a Quantitative Risk Analysis and update the results.', true),
  (4450, 0, 'تحديث سجل الافتراضات وتقييم المخاطر المرتبطة به.', 'Update the assumption log and assess the associated risks.', false),
  (4450, 1, 'تصعيد الموقف وطلب الموافقة للمضي قدمًا.', 'Escalate the situation and request approval to proceed.', false),
  (4450, 2, 'تأكيد النتائج من خلال تجربة ثانية.', 'Confirm the results through a second trial.', false),
  (4450, 3, 'إعادة تقييم تصميم التقاطعين.', 'Re-evaluate the design of the two crossings.', true),
  (4451, 0, 'المقابلات', 'Interviews', false),
  (4451, 1, 'الأسلوب الجماعي الاسمي', 'Nominal Group Technique', true),
  (4451, 2, 'أسلوب دلفي', 'Delphi Technique', false),
  (4451, 3, 'القوائم التوجيهية', 'Prompt lists', false),
  (4452, 0, 'مراجعة عتبات المخاطر والمحفزات.', 'Review the risk thresholds and triggers.', true),
  (4452, 1, 'تحديث استراتيجيات الاستجابة للمخاطر.', 'Update the risk response strategies.', false),
  (4452, 2, 'مراجعة شهية المخاطر لدى المعنيين.', 'Review the stakeholders'' risk appetite.', false),
  (4452, 3, 'توفير التدريب للمسؤولين عن تنفيذ إجراءات الاستجابة للمخاطر.', 'Provide training for the risk action owners.', false),
  (4453, 0, 'الوصف الكامل للمخاطر', 'The full risk description', true),
  (4453, 1, 'تصنيف المخاطر', 'The risk categorization', false),
  (4453, 2, 'محاكاة المخاطر', 'The risk simulation', false),
  (4453, 3, 'خطة الاستجابة للمخاطر', 'The risk response plan', false),
  (4454, 0, 'تأكد من توثيق قيود المعدات بشكل جيد وإدارتها باعتبارها مخاطرة عالية التأثير في المشروع.', 'Ensure that the equipment constraints are well documented and managed as a high-impact project risk.', true),
  (4454, 1, 'الحصول على التزام موقع من العميل بأن المعدات سيتم تسليمها في الوقت المحدد.', 'Obtain a signed commitment from the customer that the equipment will be delivered on time.', false),
  (4454, 2, 'متابعة الجدول الزمني وتقييم أفضل مسار للعمل إذا تم اكتشاف أي تأخير.', 'Monitor the schedule and assess the BEST course of action if any delay is detected.', false),
  (4454, 3, 'إثارة الموضوع مع راعي المشروع حتى يتم التعامل معها كمسألة مبيعات أو تعاقدية.', 'Raise the matter with the Project Sponsor so that it is handled as a sales or contractual matter.', false),
  (4455, 0, 'تأخير الخط أثناء أعمال تركيب مكيف الهواء', 'A line delay during the air conditioning installation work', false),
  (4455, 1, 'الحاجة المحتملة لمشاركة المساحة مع الآلات الأخرى', 'A potential need to share the space with other machinery', true),
  (4455, 2, 'نوع مختلف من المعدات التي تم استلامها قبل التثبيت', 'A different type of equipment received prior to installation', false),
  (4455, 3, 'مشكلة عدم مطابقة للجودة تم إثارتها أثناء التفتيش', 'A quality non-conformance issue raised during inspection', false),
  (4456, 0, 'إنشاء مشروع جديد للتدريب والتطوير على استخدام أدوات إدارة المخاطر.', 'Create a new project for training and development on the use of Risk Management tools.', false),
  (4456, 1, 'تسجيل جلسة تحديد المخاطر ومشاركتها مع الفريق بعد الاجتماع.', 'Record the risk identification session and share it with the team after the meeting.', false),
  (4456, 2, 'إرسال تفاصيل الاجتماع لجميع المشاركين قبل موعد الاجتماع.', 'Send the meeting details to all participants before the meeting date.', false),
  (4456, 3, 'إرسال جدول أعمال الاجتماع قبل موعد الاجتماع بوقت كافٍ.', 'Send the meeting agenda sufficiently in advance of the meeting.', true),
  (4457, 0, 'إجراء جلسة منفصلة مع الفريق الفني لتحديد مخاطرهم.', 'Hold a separate session with the technical team to identify their risks.', true),
  (4457, 1, 'إجراء تحليل للمخاطر باستخدام المعلومات المتوفرة من المبيعات والتصنيع.', 'Perform the risk analysis using the information available from sales and manufacturing.', false),
  (4457, 2, 'إعادة جدولة جلسة تحديد المخاطر وإلغاء نتائج المقابلات السابقة.', 'Reschedule the risk identification session and discard the results of the earlier interviews.', false),
  (4457, 3, 'مراجعة وثائق المشروعات السابقة بدلًا من مقابلة الفريق الفني.', 'Review documentation from previous projects instead of interviewing the technical team.', false),
  (4458, 0, 'تحديد مخاطر المشروع التي لها ارتباط إيجابي.', 'Identify the project risks that have a positive correlation.', true),
  (4458, 1, 'إضافة المخاطر ذات الصلة إلى سجل المخاطر.', 'Add the related risks to the Risk Register.', false),
  (4458, 2, 'تحديد تأثير كل خطر بصورة منفصلة.', 'Determine the impact of each risk separately.', false),
  (4458, 3, 'تحديث خطة إدارة المخاطر لتشمل جميع المتطلبات.', 'Update the Risk Management Plan to include all requirements.', false),
  (4459, 0, 'تزويد راعي البرنامج بخطة إدارة تحقيق المنافع (Benefits Realization Management Plan).', 'Provide the Program Sponsor with the Benefits Realization Management Plan.', true),
  (4459, 1, 'الاجتماع مع مديري المشاريع المكوِّنة للبرنامج وتحديث خارطة طريق البرنامج (Program Roadmap).', 'Meet with the component project managers and update the Program Roadmap.', false),
  (4459, 2, 'إعداد خطة إدارة البرنامج (Program Management Plan) وتقديمها إلى راعي البرنامج.', 'Prepare the Program Management Plan and submit it to the Program Sponsor.', false),
  (4459, 3, 'مطالبة مسؤول جدولة البرنامج بتحديث الجدول الزمني المتكامل (Integrated Schedule).', 'Ask the program scheduler to update the Integrated Schedule.', false);

